func (c *Command) Usage() error {
	_, err := io.WriteString(c.err, helpText)
	return err
}

func (c *Command) Execute() error {
	changed, showHelp, showVersion, err := c.parse(os.Args[1:])
	if err != nil {
		return err
	}
	if showHelp {
		_, err := io.WriteString(c.out, helpText)
		return err
	}
	if showVersion {
		_, err := fmt.Fprintln(c.out, "gomplate version 0.0.0")
		return err
	}

	cfg, err := c.app.resolveConfig(changed)
	if err != nil {
		return err
	}
	return c.app.run(cfg)
}

func (c *Command) parse(args []string) (map[string]bool, bool, bool, error) {
	c.app.cli = cliFlags{
		Files:      []string{"-"},
		Outs:       []string{"-"},
		OutputDir:  ".",
		LeftDelim:  "{{",
		RightDelim: "}}",
		MissingKey: "error",
		Config:     ".gomplate.yaml",
	}

	changed := map[string]bool{}
	resetList := func(name string, target *[]string) {
		if !changed[name] {
			*target = nil
		}
		changed[name] = true
	}
	requireValue := func(current string, args []string, index *int) (string, error) {
		if current != "" {
			return current, nil
		}
		*index++
		if *index >= len(args) {
			return "", usageErrorf("flag needs an argument")
		}
		return args[*index], nil
	}

	showHelp := false
	showVersion := false

	for index := 0; index < len(args); index++ {
		arg := args[index]
		switch {
		case arg == "-h" || arg == "--help":
			showHelp = true
		case arg == "-v" || arg == "--version":
			showVersion = true
		case arg == "-V" || arg == "--verbose":
			c.app.cli.Verbose = true
			changed["verbose"] = true
		case arg == "--experimental":
			c.app.cli.Experimental = true
			changed["experimental"] = true
		case arg == "--exec-pipe":
			c.app.cli.ExecPipe = true
			changed["exec-pipe"] = true
		default:
			name, value, ok := splitLongFlag(arg)
			if ok {
				if err := c.applyLongFlag(name, value, args, &index, changed, resetList, requireValue); err != nil {
					return nil, false, false, err
				}
				continue
			}
			if err := c.applyShortFlag(arg, args, &index, changed, resetList, requireValue); err != nil {
				return nil, false, false, err
			}
		}
	}

	return changed, showHelp, showVersion, nil
}

func splitLongFlag(arg string) (string, string, bool) {
	if !strings.HasPrefix(arg, "--") {
		return "", "", false
	}
	body := strings.TrimPrefix(arg, "--")
	if name, value, ok := strings.Cut(body, "="); ok {
		return name, value, true
	}
	return body, "", true
}

