func defaultRuntimeConfig() *RuntimeConfig {
	return &RuntimeConfig{
		Context:       map[string]DatasourceConfig{},
		Datasources:   map[string]DatasourceConfig{},
		LeftDelim:     "{{",
		MissingKey:    "error",
		OutputDir:     ".",
		PluginTimeout: 5 * time.Second,
		Plugins:       map[string]PluginConfig{},
		RightDelim:    "}}",
		Templates:     map[string]DatasourceConfig{},
	}
}

func (a *App) resolveConfig(changed map[string]bool) (*RuntimeConfig, error) {
	cfg := defaultRuntimeConfig()

	if value, ok := os.LookupEnv("GOMPLATE_LEFT_DELIM"); ok {
		cfg.LeftDelim = value
	}
	if value, ok := os.LookupEnv("GOMPLATE_RIGHT_DELIM"); ok {
		cfg.RightDelim = value
	}
	if value, ok := os.LookupEnv("GOMPLATE_EXPERIMENTAL"); ok {
		if parsed, err := strconv.ParseBool(value); err == nil {
			cfg.Experimental = parsed
		}
	}

	configPath, configExplicit, err := resolveConfigPath(changed, a.cli.Config)
	if err != nil {
		return nil, err
	}
	if configPath != "" {
		fileCfg, loadErr := loadConfigFile(configPath)
		if loadErr != nil {
			if !configExplicit && errors.Is(loadErr, os.ErrNotExist) {
				goto applyCLI
			}
			return nil, loadErr
		}
		applyFileConfig(cfg, fileCfg)
	}

