		for _, raw := range a.cli.Datasources {
			alias, ds, err := parseDatasourceArg(raw)
			if err != nil {
				return nil, err
			}
			cfg.Datasources[alias] = mergeDatasource(cfg.Datasources[alias], ds)
		}
	}

	if changed["datasource-header"] {
		for _, raw := range a.cli.DatasourceHeaders {
			alias, name, value, err := parseHeaderArg(raw)
			if err != nil {
				return nil, err
			}
			ds := cfg.Datasources[alias]
			if ds.Header == nil {
