func resolveConfigPath(changed map[string]bool, cliValue string) (string, bool, error) {
	if changed["config"] {
		return cliValue, true, nil
	}
	if value, ok := os.LookupEnv("GOMPLATE_CONFIG"); ok {
		return value, value != "", nil
	}
	return ".gomplate.yaml", false, nil
}

func applyFileConfig(dst *RuntimeConfig, src FileConfig) {
	if src.Chmod != "" {
		dst.Chmod = src.Chmod
	}
	mergeDatasources(dst.Context, src.Context)
	mergeDatasources(dst.Datasources, src.Datasources)
	if len(src.Excludes) > 0 {
		dst.Excludes = append([]string(nil), src.Excludes...)
	}
	if len(src.ExcludeProcessing) > 0 {
		dst.ExcludeProcessing = append([]string(nil), src.ExcludeProcessing...)
	}
	if src.ExecPipe {
		dst.ExecPipe = true
	}
	if src.Experimental {
		dst.Experimental = true
	}
	if src.In != "" {
		value := src.In
		dst.In = &value
	}
	if src.InputDir != "" {
		dst.InputDir = src.InputDir
	}
	if len(src.InputFiles) > 0 {
		dst.InputFiles = append([]string(nil), src.InputFiles...)
	}
	if src.LeftDelim != "" {
		dst.LeftDelim = src.LeftDelim
	}
	if src.MissingKey != "" {
		dst.MissingKey = src.MissingKey
	}
	if src.OutputDir != "" {
		dst.OutputDir = src.OutputDir
	}
	if len(src.OutputFiles) > 0 {
		dst.OutputFiles = append([]string(nil), src.OutputFiles...)
	}
	if src.OutputMap != "" {
		dst.OutputMap = src.OutputMap
	}
	for name, plugin := range src.Plugins {
		dst.Plugins[name] = plugin
	}
	if src.PluginTimeout > 0 {
		dst.PluginTimeout = src.PluginTimeout
	}
	if src.RightDelim != "" {
		dst.RightDelim = src.RightDelim
	}
	mergeDatasources(dst.Templates, src.Templates)
}

func validateRuntimeConfig(cfg *RuntimeConfig) error {
	switch cfg.MissingKey {
	case "error", "default", "invalid", "zero":
	default:
		return fmt.Errorf("failed to validate config: unsupported missingKey %q", cfg.MissingKey)
	}

	if cfg.PluginTimeout <= 0 {
		cfg.PluginTimeout = 5 * time.Second
	}

	if cfg.In != nil {
		if cfg.InputDir != "" {
			return fmt.Errorf("failed to validate config: inputDir may not be used with in")
		}
		if len(cfg.OutputFiles) == 0 {
			cfg.OutputFiles = []string{"-"}
		}
		return nil
	}

	if cfg.InputDir != "" {
		if len(cfg.InputFiles) > 0 {
			return fmt.Errorf("failed to validate config: inputFiles may not be used with inputDir")
		}
		if len(cfg.OutputFiles) > 0 {
			return fmt.Errorf("failed to validate config: outputFiles may not be used with inputDir")
		}
		if cfg.OutputDir == "" {
			cfg.OutputDir = "."
		}
		return nil
	}

	if len(cfg.InputFiles) == 0 {
		cfg.InputFiles = []string{"-"}
	}
	if len(cfg.OutputFiles) == 0 {
		cfg.OutputFiles = []string{"-"}
	}
	if len(cfg.InputFiles) != len(cfg.OutputFiles) {
		return fmt.Errorf("failed to validate config: must provide same number of 'outputFiles' (%d) as 'in' or 'inputFiles' (%d) options\n---\n%s", len(cfg.OutputFiles), len(cfg.InputFiles), cfg.debugString())
	}
	return nil
}

func (cfg *RuntimeConfig) debugString() string {
	var builder strings.Builder
	if len(cfg.InputFiles) > 0 {
		fmt.Fprintf(&builder, "inputFiles: [%s]\n", strings.Join(cfg.InputFiles, ", "))
	}
	if len(cfg.OutputFiles) > 0 {
		fmt.Fprintf(&builder, "outputFiles: [%s]\n", strings.Join(cfg.OutputFiles, ", "))
	}
	fmt.Fprintf(&builder, "leftDelim: '%s'\n", cfg.LeftDelim)
	fmt.Fprintf(&builder, "rightDelim: '%s'\n", cfg.RightDelim)
	fmt.Fprintf(&builder, "missingKey: %s\n", cfg.MissingKey)
	fmt.Fprintf(&builder, "pluginTimeout: %s\n", cfg.PluginTimeout)
	return builder.String()
}

func parseDatasourceArg(raw string) (string, DatasourceConfig, error) {
	alias, target, err := parseAliasedPathArg(raw, true)
	if err != nil {
		return "", DatasourceConfig{}, err
	}
	return alias, DatasourceConfig{URL: target}, nil
}

func parseTemplateArg(raw string) (string, DatasourceConfig, error) {
	if alias, target, ok := splitAssignment(raw); ok {
		if alias == "" || target == "" {
			return "", DatasourceConfig{}, usageErrorf("invalid argument (%s)", raw)
		}
		return alias, DatasourceConfig{URL: target}, nil
	}
	return raw, DatasourceConfig{URL: raw}, nil
}

func parsePluginArg(raw string, timeout time.Duration) (string, PluginConfig, error) {
	name, path, ok := splitAssignment(raw)
	if !ok || name == "" || path == "" {
		return "", PluginConfig{}, usageErrorf("invalid argument (%s)", raw)
	}
	return name, PluginConfig{Cmd: path, Timeout: timeout}, nil
}

func parseHeaderArg(raw string) (string, string, string, error) {
	alias, value, ok := splitAssignment(raw)
	if !ok || alias == "" {
		return "", "", "", usageErrorf("invalid argument (%s)", raw)
	}
	parts := strings.SplitN(value, ":", 2)
	if len(parts) != 2 {
		return "", "", "", usageErrorf("invalid argument (%s)", raw)
	}
	name := strings.TrimSpace(parts[0])
	headerValue := strings.TrimSpace(parts[1])
	if name == "" {
		return "", "", "", usageErrorf("invalid argument (%s)", raw)
	}
	return alias, name, headerValue, nil
}

func parseAliasedPathArg(raw string, inferAlias bool) (string, string, error) {
	if alias, value, ok := splitAssignment(raw); ok {
		if alias == "" || value == "" {
			return "", "", usageErrorf("invalid argument (%s)", raw)
		}
		return alias, value, nil
	}
	if !inferAlias {
		return "", "", usageErrorf("invalid argument (%s)", raw)
	}

	if looksLikeURL(raw) || isAbsolutePath(raw) {
		return "", "", usageErrorf("invalid argument (%s): must provide an alias with files not in working directory", raw)
	}

	clean := filepath.Clean(raw)
	if filepath.Dir(clean) != "." {
		return "", "", usageErrorf("invalid argument (%s): must provide an alias with files not in working directory", raw)
	}

	base := filepath.Base(clean)
	ext := filepath.Ext(base)
	alias := strings.TrimSuffix(base, ext)
	if alias == "" {
		return "", "", usageErrorf("invalid argument (%s)", raw)
	}
	return alias, raw, nil
}

func mergeDatasource(dst, src DatasourceConfig) DatasourceConfig {
	if src.URL != "" {
		dst.URL = src.URL
	}
	if len(src.Header) > 0 {
		if dst.Header == nil {
			dst.Header = map[string][]string{}
		}
		for name, values := range src.Header {
			dst.Header[name] = append([]string(nil), values...)
		}
	}
	return dst
}

func mergeDatasources(dst map[string]DatasourceConfig, src map[string]DatasourceConfig) {
	for alias, ds := range src {
		dst[alias] = mergeDatasource(dst[alias], ds)
	}
}

func splitAssignment(raw string) (string, string, bool) {
	index := strings.Index(raw, "=")
	if index < 0 {
		return "", "", false
	}
	return raw[:index], raw[index+1:], true
}

func looksLikeURL(raw string) bool {
	if strings.HasPrefix(raw, "file://") || strings.HasPrefix(raw, "env:") || strings.HasPrefix(raw, "stdin:") {
		return true
	}
	if strings.HasPrefix(raw, "http://") || strings.HasPrefix(raw, "https://") {
		return true
	}
	return false
}

func isAbsolutePath(raw string) bool {
	return strings.HasPrefix(raw, "/")
}

