func newDatasourceManager(cfg *RuntimeConfig, stdin func() ([]byte, error)) *datasourceManager {
	defs := map[string]DatasourceConfig{}
	for alias, def := range cfg.Datasources {
		defs[alias] = def
	}

	typeParam := os.Getenv("GOMPLATE_TYPE_PARAM")
	if typeParam == "" {
		typeParam = "type"
	}

	return &datasourceManager{
		defs:      defs,
		readStdin: stdin,
		typeParam: typeParam,
	}
}

func (m *datasourceManager) stdin() ([]byte, error) {
	return m.readStdin()
}

func (m *datasourceManager) loadContext(defs map[string]DatasourceConfig) (any, error) {
	root := any(map[string]any{})

	aliases := make([]string, 0, len(defs))
	for alias := range defs {
		aliases = append(aliases, alias)
	}
	sort.Strings(aliases)

	for _, alias := range aliases {
		value, err := m.loadParsedFromDef(defs[alias], "")
		if err != nil {
			return nil, err
		}
		if alias == "." {
			root = value
			continue
		}
		if contextMap, ok := root.(map[string]any); ok {
			contextMap[alias] = value
		}
	}

	if root == nil {
		return map[string]any{}, nil
	}
	return root, nil
}

func (m *datasourceManager) Exists(alias string) bool {
	m.mu.RLock()
	defer m.mu.RUnlock()
	_, ok := m.defs[alias]
	return ok
}

func (m *datasourceManager) Reachable(alias string) bool {
	if !m.Exists(alias) {
		return false
	}
	_, err := m.LoadParsed(alias)
	return err == nil
}

func (m *datasourceManager) List() []string {
	m.mu.RLock()
	defer m.mu.RUnlock()

	names := make([]string, 0, len(m.defs))
	for alias := range m.defs {
		names = append(names, alias)
	}
	sort.Strings(names)
	return names
}

func (m *datasourceManager) DefineIfMissing(alias string, def DatasourceConfig) {
	m.mu.Lock()
	defer m.mu.Unlock()
	if _, ok := m.defs[alias]; !ok {
		m.defs[alias] = def
	}
}

func (m *datasourceManager) LoadParsed(alias string, subpaths ...string) (any, error) {
	subpath := ""
	if len(subpaths) > 0 {
		subpath = subpaths[0]
	}

	m.mu.RLock()
	def, ok := m.defs[alias]
	m.mu.RUnlock()
	if !ok {
		if !looksDynamicDatasource(alias) {
			return nil, fmt.Errorf("undefined datasource '%s': %w", alias, nil)
		}
		def = DatasourceConfig{URL: alias}
	}

	return m.loadParsedFromDef(def, subpath)
}

func (m *datasourceManager) Include(alias string, subpaths ...string) (string, error) {
	subpath := ""
	if len(subpaths) > 0 {
		subpath = subpaths[0]
	}

	m.mu.RLock()
	def, ok := m.defs[alias]
	m.mu.RUnlock()
	if !ok {
		if !looksDynamicDatasource(alias) {
			return "", fmt.Errorf("undefined datasource '%s': %w", alias, nil)
		}
		def = DatasourceConfig{URL: alias}
	}

	return m.loadRawFromDef(def, subpath)
}

func (m *datasourceManager) loadTemplate(def DatasourceConfig) (string, error) {
	return m.loadRawFromDef(def, "")
}

func (m *datasourceManager) loadParsedFromDef(def DatasourceConfig, subpath string) (any, error) {
	result, err := m.loadSource(def, subpath)
	if err != nil {
		return nil, err
	}
	if result.directory != nil {
		return result.directory, nil
	}
	return parseByMime(result.bytes, result.mimeType)
}

func (m *datasourceManager) loadRawFromDef(def DatasourceConfig, subpath string) (string, error) {
	result, err := m.loadSource(def, subpath)
	if err != nil {
		return "", err
	}
	if result.directory != nil {
		return "", fmt.Errorf("can not include directory datasource")
	}
	return string(result.bytes), nil
}

func (m *datasourceManager) loadSource(def DatasourceConfig, subpath string) (sourceResult, error) {
	var out sourceResult

	if def.URL == "" {
		return out, fmt.Errorf("empty datasource URL")
	}

	parsed, err := url.Parse(def.URL)
	if err != nil {
		return out, err
	}

	overrideType := parsed.Query().Get(m.typeParam)

	switch parsed.Scheme {
	case "stdin":
		body, err := m.stdin()
		if err != nil {
			return out, err
		}
		fakeName := strings.TrimPrefix(parsed.Path, "/")
		if fakeName == "" {
			fakeName = strings.TrimPrefix(parsed.Opaque, "/")
		}
		if fakeName == "" {
			fakeName = subpath
		}
		out.bytes = body
		out.mimeType = detectMime(fakeName, overrideType, "")
		return out, nil
	case "env":
		name := strings.TrimPrefix(parsed.Path, "/")
		if name == "" {
			name = strings.TrimPrefix(parsed.Opaque, "/")
		}
		if name == "" {
			name = subpath
		}
		value, _ := os.LookupEnv(name)
		out.bytes = []byte(value)
		out.mimeType = detectMime(name, overrideType, "")
		return out, nil
	case "http", "https":
		target := def.URL
		if subpath != "" {
			copyURL := *parsed
			copyURL.Path = path.Join(copyURL.Path, subpath)
			target = copyURL.String()
		}
		req, err := http.NewRequest(http.MethodGet, target, nil)
		if err != nil {
			return out, err
		}
		for name, values := range def.Header {
			for _, value := range values {
				req.Header.Add(name, value)
			}
		}
		resp, err := http.DefaultClient.Do(req)
		if err != nil {
			return out, err
		}
		defer resp.Body.Close()
		if resp.StatusCode >= 400 {
			return out, fmt.Errorf("unexpected HTTP status %s", resp.Status)
		}
		body, err := io.ReadAll(resp.Body)
		if err != nil {
			return out, err
		}
		out.bytes = body
		out.mimeType = detectMime(path.Base(req.URL.Path), overrideType, resp.Header.Get("Content-Type"))
		return out, nil
	default:
		localPath, _, ok := localFilePath(def.URL)
		if !ok {

		if !ok {
			return out, fmt.Errorf("unsupported datasource URL %q", def.URL)
		}
		if subpath != "" {
			localPath = filepath.Join(localPath, filepath.FromSlash(subpath))
		}
		info, err := os.Stat(localPath)
		if err != nil {
			return out, err
		}
		if info.IsDir() {
			entries, err := os.ReadDir(localPath)
			if err != nil {
				return out, err
			}
			names := make([]string, 0, len(entries))
			for _, entry := range entries {
				names = append(names, entry.Name())
			}
			sort.Strings(names)
			out.directory = names
			return out, nil
		}
		body, err := os.ReadFile(localPath)
		if err != nil {
			return out, err
		}
		out.bytes = body
		out.mimeType = detectMime(localPath, overrideType, "")
		return out, nil
	}
}

func localFilePath(raw string) (string, bool, bool) {
	parsed, err := url.Parse(raw)
	if err != nil {
		return "", false, false
	}
	if parsed.Scheme != "" && parsed.Scheme != "file" {
		return "", false, false
	}

	pathValue := raw
	if parsed.Scheme == "file" {
		pathValue = parsed.Path
		if pathValue == "" {
			pathValue = parsed.Opaque
		}
		unescaped, err := url.PathUnescape(pathValue)
		if err == nil {
			pathValue = unescaped
		}
	} else {
		pathValue = parsed.Path
		if pathValue == "" {
			pathValue = raw
		}
	}

	info, err := os.Stat(pathValue)
	if err == nil {
		return pathValue, info.IsDir(), true
	}
	return pathValue, strings.HasSuffix(pathValue, string(os.PathSeparator)) || strings.HasSuffix(pathValue, "/"), true
}

func looksDynamicDatasource(raw string) bool {
	if looksLikeURL(raw) {
		return true
	}
	if filepath.IsAbs(raw) {
		return true
	}
	return strings.HasPrefix(raw, "./") || strings.HasPrefix(raw, "../")
}

func detectMime(name, override, contentType string) string {
	if override != "" {
		return strings.ToLower(override)
	}
	if contentType != "" {
		mediaType, _, err := mime.ParseMediaType(contentType)
		if err == nil && mediaType != "" {
			return strings.ToLower(mediaType)
		}
	}
	switch strings.ToLower(filepath.Ext(name)) {
	case ".json":
		return "application/json"
	case ".yaml", ".yml":
		return "application/yaml"
	case ".toml":
		return "application/toml"
	case ".csv":
		return "text/csv"
	case ".env":
		return "application/x-env"
	default:
		return "text/plain"
	}
}

func parseByMime(data []byte, mimeType string) (any, error) {
	switch strings.ToLower(mimeType) {
	case "", "text/plain":
		return string(data), nil
	case "application/json":
		var value any
		if err := json.Unmarshal(data, &value); err != nil {
			return nil, err
		}
		return value, nil
	case "application/array+json":
		var value []any
		if err := json.Unmarshal(data, &value); err != nil {
			return nil, err
		}
		return value, nil
	case "application/yaml":
		var value any
		if err := yaml.Unmarshal(data, &value); err != nil {
			return nil, err
		}
		return value, nil
	case "application/toml":
		var value map[string]any
		if err := toml.Unmarshal(data, &value); err != nil {
			return nil, err
		}
		return value, nil
	case "text/csv":
		reader := csv.NewReader(strings.NewReader(string(data)))
		return reader.ReadAll()
	case "application/x-env":
		return parseEnvDocument(string(data))
	default:
		return nil, fmt.Errorf("unsupported MIME type %s", mimeType)
	}
}

func parseEnvDocument(input string) (map[string]string, error) {
	result := map[string]string{}
	lines := strings.Split(input, "\n")

	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		if strings.HasPrefix(line, "export ") {
			line = strings.TrimSpace(strings.TrimPrefix(line, "export "))
		}
		key, value, ok := strings.Cut(line, "=")
		if !ok {
			continue
		}
		key = strings.TrimSpace(key)
		value = strings.TrimSpace(value)

		switch {
		case strings.HasPrefix(value, "'") && strings.HasSuffix(value, "'") && len(value) >= 2:

		case strings.HasPrefix(value, "'") && strings.HasSuffix(value, "'") && len(value) >= 2:
