			if err != nil {
				return nil, err
			}
			value = expandWithEnv(unquoted, result)
		default:
			value = expandWithEnv(value, result)
		}
		result[key] = value
	}

	return result, nil
}

func expandWithEnv(input string, current map[string]string) string {
	return os.Expand(input, func(key string) string {
		if value, ok := current[key]; ok {
			return value
		}
		return os.Getenv(key)
	})
}

