func cidrNetmask(prefix netip.Prefix) (netip.Addr, error) {
	totalBits := addrBitLen(prefix.Addr())
	bits := prefix.Bits()
	if bits < 0 || bits > totalBits {
		return netip.Addr{}, fmt.Errorf("invalid prefix length")
	}

	mask := make([]byte, totalBits/8)
	remaining := bits
	for index := range mask {
		switch {
		case remaining >= 8:
			mask[index] = 0xff
			remaining -= 8
		case remaining > 0:
			mask[index] = byte(0xff << (8 - remaining))
			remaining = 0
		default:
			mask[index] = 0
		}
	}
	return bytesToAddr(mask), nil
}

func cidrHost(prefix netip.Prefix, host int64) (netip.Addr, error) {
	if host < 0 {
		return netip.Addr{}, fmt.Errorf("host number must be >= 0")
	}
	prefix = prefix.Masked()
	totalBits := addrBitLen(prefix.Addr())
	hostBits := totalBits - prefix.Bits()
	limit := pow2(hostBits)
	hostBig := big.NewInt(host)
	if hostBig.Cmp(limit) >= 0 {
		return netip.Addr{}, fmt.Errorf("host number out of range")
	}

	base := addrToBig(prefix.Addr())
	addr := new(big.Int).Add(base, hostBig)
	return bigToAddr(addr, totalBits)
}

func cidrSubnets(prefix netip.Prefix, newbits int64) ([]netip.Prefix, error) {
	if newbits < 0 {
		return nil, fmt.Errorf("newbits must be >= 0")
	}
	prefix = prefix.Masked()
	totalBits := addrBitLen(prefix.Addr())
	newLen := prefix.Bits() + int(newbits)
	if newLen > totalBits {
		return nil, fmt.Errorf("prefix length out of range")
	}
	if newbits > 20 {
		return nil, fmt.Errorf("newbits too large")
	}

	count := 1 << uint(newbits)
	step := pow2(totalBits - newLen)
	base := addrToBig(prefix.Addr())

	results := make([]netip.Prefix, 0, count)
	current := new(big.Int).Set(base)
	for index := 0; index < count; index++ {
		addr, err := bigToAddr(current, totalBits)
		if err != nil {
			return nil, err
		}
		results = append(results, netip.PrefixFrom(addr, newLen))
		current = new(big.Int).Add(current, step)
	}
	return results, nil
}

func cidrSubnetSizes(prefix netip.Prefix, sizes []int64) ([]netip.Prefix, error) {
	prefix = prefix.Masked()
	totalBits := addrBitLen(prefix.Addr())
	base := addrToBig(prefix.Addr())
	cursor := new(big.Int).Set(base)
	limit := new(big.Int).Add(base, pow2(totalBits-prefix.Bits()))

	results := make([]netip.Prefix, 0, len(sizes))
	for _, size := range sizes {
		if size < 0 {
			return nil, fmt.Errorf("newbits must be >= 0")
		}
		newLen := prefix.Bits() + int(size)
		if newLen > totalBits {
			return nil, fmt.Errorf("prefix length out of range")
		}
		blockSize := pow2(totalBits - newLen)
		relative := new(big.Int).Sub(cursor, base)
		quotient, remainder := new(big.Int), new(big.Int)
		quotient.QuoRem(relative, blockSize, remainder)
		if remainder.Sign() != 0 {
			quotient.Add(quotient, big.NewInt(1))
		}
		start := new(big.Int).Mul(quotient, blockSize)
		start.Add(start, base)
		next := new(big.Int).Add(start, blockSize)
		if next.Cmp(limit) > 0 {
			return nil, fmt.Errorf("subnet out of range")
		}
		addr, err := bigToAddr(start, totalBits)
		if err != nil {
			return nil, err
		}
		results = append(results, netip.PrefixFrom(addr, newLen))
		cursor = next
	}
	return results, nil
}

func addrBitLen(addr netip.Addr) int {
	if addr.Is4() {
		return 32
	}
	return 128
}

func addrToBig(addr netip.Addr) *big.Int {
	if addr.Is4() {
		bytes := addr.As4()
		return new(big.Int).SetBytes(bytes[:])
	}
	bytes := addr.As16()
	return new(big.Int).SetBytes(bytes[:])
}

func bigToAddr(value *big.Int, bits int) (netip.Addr, error) {
	if value.Sign() < 0 {
		return netip.Addr{}, fmt.Errorf("negative address")
	}
	size := bits / 8
	data := value.FillBytes(make([]byte, size))
	return bytesToAddr(data), nil
}

func bytesToAddr(data []byte) (netip.Addr, error) {
	switch len(data) {
	case 4:
		var addr [4]byte
		copy(addr[:], data)
		return netip.AddrFrom4(addr), nil
	case 16:
		var addr [16]byte
		copy(addr[:], data)
		return netip.AddrFrom16(addr), nil
	default:
		return netip.Addr{}, fmt.Errorf("unsupported address length %d", len(data))
	}
}

func pow2(bits int) *big.Int {
	return new(big.Int).Lsh(big.NewInt(1), uint(bits))
}

package gomplate

import (
	"bufio"
	"os"
	"path"
	"path/filepath"
	"strings"

	"github.com/bmatcuk/doublestar/v4"
)

type pathPattern struct {
	base   string
	pat    string
	negate bool
}

func shouldSkipFile(inputDir, rel string, cfg *RuntimeConfig) (bool, bool, error) {
	if len(cfg.Includes) > 0 {
		includePatterns := compilePatterns("", cfg.Includes)
		if !matchesAny(includePatterns, rel) {
			return true, false, nil
		}
	}

	excludePatterns := compilePatterns("", cfg.Excludes)
	ignorePatterns, err := loadIgnorePatterns(inputDir, rel)
	if err != nil {
		return false, false, err
	}
	if evaluatePatterns(append(excludePatterns, ignorePatterns...), rel) {
		return true, false, nil
	}

	copyOnly := evaluatePatterns(compilePatterns("", cfg.ExcludeProcessing), rel)
	return false, copyOnly, nil
}

func compilePatterns(base string, raw []string) []pathPattern {
	patterns := make([]pathPattern, 0, len(raw))
	for _, item := range raw {
		line := strings.TrimSpace(item)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		pattern := pathPattern{base: filepath.ToSlash(base)}
		if strings.HasPrefix(line, "!") {
			pattern.negate = true
			line = strings.TrimSpace(strings.TrimPrefix(line, "!"))
		}
		pattern.pat = line
		patterns = append(patterns, pattern)
	}
	return patterns
}

func loadIgnorePatterns(inputDir, rel string) ([]pathPattern, error) {
	var patterns []pathPattern

	dir := path.Dir(rel)
	if dir == "." {
		dir = ""
	}

	ancestors := []string{""}
	if dir != "" {
		parts := strings.Split(dir, "/")
		current := ""
		for _, part := range parts {
			if current == "" {
				current = part
			} else {
				current = path.Join(current, part)
			}
			ancestors = append(ancestors, current)
		}
	}

	for _, ancestor := range ancestors {
		ignorePath := filepath.Join(inputDir, filepath.FromSlash(ancestor), ".gomplateignore")
		file, err := os.Open(ignorePath)
		if err != nil {
			if os.IsNotExist(err) {
				continue
			}
			return nil, err
		}

		var lines []string
		scanner := bufio.NewScanner(file)
		for scanner.Scan() {
			lines = append(lines, scanner.Text())
		}
		closeErr := file.Close()
		if err := scanner.Err(); err != nil {
			return nil, err
		}
		if closeErr != nil {
			return nil, closeErr
		}

		patterns = append(patterns, compilePatterns(ancestor, lines)...)
	}

	return patterns, nil
}

func matchesAny(patterns []pathPattern, rel string) bool {
	for _, pattern := range patterns {
		if pattern.matches(rel) {
			return true
		}
	}
	return false
}

func evaluatePatterns(patterns []pathPattern, rel string) bool {
	ignored := false
	for _, pattern := range patterns {
		if pattern.matches(rel) {
			ignored = !pattern.negate
		}
	}
	return ignored
}

func (p pathPattern) matches(rel string) bool {
	rel = filepath.ToSlash(rel)
	base := strings.Trim(filepath.ToSlash(p.base), "/")
	pattern := strings.TrimSpace(p.pat)
	if pattern == "" {
		return false
	}

	target := rel
	if base != "" {
		if rel != base && !strings.HasPrefix(rel, base+"/") {
			return false
		}
		target = strings.TrimPrefix(rel, base)
		target = strings.TrimPrefix(target, "/")
	}

	dirOnly := strings.HasSuffix(pattern, "/")
	pattern = strings.TrimPrefix(pattern, "/")
	pattern = strings.TrimSuffix(pattern, "/")

	if dirOnly {
		if pattern == "" {
			return false
		}
		if strings.Contains(target, pattern+"/") || target == pattern {
			return true
		}
		return false
	}

	if !strings.Contains(pattern, "/") {
		parts := strings.Split(target, "/")
		for _, part := range parts {
			ok, _ := doublestar.Match(pattern, part)
			if ok {
				return true
			}
		}
		return false
	}

	ok, _ := doublestar.Match(pattern, target)
	return ok
}

